; tiles3.asm -- chapter 22: the tiles written into each third
; generated by gen22.py
        INCLUDE "msx.inc"
        OUTPUT "tiles3.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A picture of 8 tiles, 8 x 8 each with a colour for every line, and a
; map of 768 names. The tiles are written into each of the three thirds.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $FF          ; colours  $2000
        VDP_REG 4, $03          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; backdrop white
        VRAM_WRITE $0000        ; every byte of the VRAM: noise, the
        ld hl, $0000            ; BIOS's first 16 KB (chapter 21)
        ld c, VDP_DATA
        ld d, 64
noise:  ld b, 0
        otir
        dec d
        jr nz, noise
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $1800        ; the map: 768 names
        ld hl, map
        ld c, VDP_DATA
        ld d, 3
nm:     ld b, 0
        otir
        dec d
        jr nz, nm
set0:
        VRAM_WRITE $0000        ; the shapes, in third 0
        ld hl, shapes
        ld b, 64
        otir
        VRAM_WRITE $2000        ; their colours, in third 0
        ld hl, colours
        ld b, 64
        otir
        VRAM_WRITE $0800        ; the shapes, in third 1
        ld hl, shapes
        ld b, 64
        otir
        VRAM_WRITE $2800        ; their colours, in third 1
        ld hl, colours
        ld b, 64
        otir
        VRAM_WRITE $1000        ; the shapes, in third 2
        ld hl, shapes
        ld b, 64
        otir
        VRAM_WRITE $3000        ; their colours, in third 2
        ld hl, colours
        ld b, 64
        otir
set1:
        VDP_REG 1, $C0          ; the display on
done:   jr done
shapes:
        db $00, $00, $00, $00, $00, $00, $00, $00, $03, $0F, $1F, $7F
        db $FF, $FF, $7F, $00, $C3, $FF, $FF, $FF, $FF, $FF, $FF, $00
        db $C0, $F0, $F8, $FE, $FF, $FF, $FE, $00, $00, $22, $77, $FF
        db $00, $44, $00, $11, $FF, $80, $80, $80, $FF, $08, $08, $08
        db $00, $66, $99, $00, $00, $66, $99, $00, $18, $18, $18, $18
        db $18, $18, $18, $18
